import csv
import json
import os
from datetime import datetime
from collections import defaultdict

INPUT_DIR = '/app/input'
OUTPUT_DIR = '/app/output'
JSON_OUTPUT = os.path.join(OUTPUT_DIR, 'expedition_summary.json')
CSV_OUTPUT = os.path.join(OUTPUT_DIR, 'quality_report.csv')

REQUIRED_FIELDS = ['recording_id', 'timestamp', 'duration_seconds', 'location', 'quality_score']

os.makedirs(OUTPUT_DIR, exist_ok=True)

def parse_timestamp(ts_str):
    """Parse timestamp string in ISO format (YYYY-MM-DD HH:MM:SS)."""
    if ts_str is None:
        return None
    try:
        return datetime.strptime(ts_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None

def main():
    valid_records = []
    processed_files = []
    invalid_counts = {
        'missing_required': 0,
        'invalid_duration': 0,
        'invalid_quality': 0,
        'invalid_timestamp': 0,
        'duration_nonpositive': 0,
        'quality_low': 0,
    }
    location_data = defaultdict(lambda: {
        'durations': [],
        'qualities': [],
        'timestamps': [],
        'hourly_counts': [0]*24,
    })

    csv_files = [f for f in os.listdir(INPUT_DIR) if f.endswith('.csv')]
    if not csv_files:
        print('No CSV files found in', INPUT_DIR)
        with open(JSON_OUTPUT, 'w') as f:
            json.dump({
                'processed_files': [],
                'total_recordings': 0,
                'locations': {}
            }, f, indent=2)
        with open(CSV_OUTPUT, 'w') as f:
            f.write('recording_id,location,duration_seconds,quality_score,hour_of_day\n')
        return

    for filename in csv_files:
        filepath = os.path.join(INPUT_DIR, filename)
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                if reader.fieldnames is None:
                    print(f'File {filename} has no headers, skipping')
                    continue
                processed_files.append(filename)
                for row in reader:
                    # Check required fields present and non-empty
                    missing = False
                    for field in REQUIRED_FIELDS:
                        val = row.get(field)
                        if val is None or val == '':
                            missing = True
                            break
                    if missing:
                        invalid_counts['missing_required'] += 1
                        continue

                    dt = parse_timestamp(row['timestamp'])
                    if dt is None:
                        invalid_counts['invalid_timestamp'] += 1
                        continue

                    try:
                        duration = float(row['duration_seconds'])
                    except ValueError:
                        invalid_counts['invalid_duration'] += 1
                        continue

                    try:
                        quality = int(row['quality_score'])
                    except ValueError:
                        invalid_counts['invalid_quality'] += 1
                        continue

                    if duration <= 0:
                        invalid_counts['duration_nonpositive'] += 1
                        continue

                    if quality < 20:
                        invalid_counts['quality_low'] += 1
                        continue

                    location_norm = row['location'].strip().lower()
                    hour_of_day = dt.hour

                    valid_records.append({
                        'recording_id': row['recording_id'],
                        'location': row['location'].strip(),
                        'duration_seconds': duration,
                        'quality_score': quality,
                        'hour_of_day': hour_of_day,
                    })

                    loc = location_data[location_norm]
                    loc['durations'].append(duration)
                    loc['qualities'].append(quality)
                    loc['timestamps'].append(dt)
                    loc['hourly_counts'][hour_of_day] += 1
        except Exception as e:
            print(f'Error processing file {filename}: {e}')

    total_recordings = len(valid_records)
    locations_summary = {}
    for loc_name, data in location_data.items():
        if not data['timestamps']:
            continue
        locations_summary[loc_name] = {
            'recording_count': len(data['durations']),
            'avg_duration_seconds': round(sum(data['durations']) / len(data['durations']), 2),
            'avg_quality_score': round(sum(data['qualities']) / len(data['qualities']), 2),
            'time_range': {
                'earliest': min(data['timestamps']).strftime('%Y-%m-%d %H:%M:%S'),
                'latest': max(data['timestamps']).strftime('%Y-%m-%d %H:%M:%S'),
            },
            'hourly_distribution': data['hourly_counts'],
        }

    with open(JSON_OUTPUT, 'w') as f:
        json.dump({
            'processed_files': processed_files,
            'total_recordings': total_recordings,
            'locations': locations_summary,
        }, f, indent=2)

    valid_records.sort(key=lambda x: x['quality_score'], reverse=True)
    with open(CSV_OUTPUT, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['recording_id', 'location', 'duration_seconds', 'quality_score', 'hour_of_day'])
        writer.writeheader()
        for rec in valid_records:
            writer.writerow(rec)

    print(f'Processed {len(processed_files)} files.')
    print(f'Total valid recordings: {total_recordings}')
    print(f'Invalid records breakdown: {invalid_counts}')

if __name__ == '__main__':
    main()
